    47	 * two promos never compounds and the order they are applied in cannot matter.
    48	 * Percentages round up: a sub-cent remainder goes to the customer, matching the
    49	 * way surcharges round down. The result is capped at the subtotal.
    50	 */
    51	export function discountCents(promos: Promo[], subtotalCents: number): number {
    52	  let total = 0;
    53	  for (const promo of promos) {
